import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_dedupe_last_record_wins_then_sorts_by_day_and_id():
    old, b, c, new = parse_transcript_log(["a,8,1", "b,4,0", "c,1,1", "a,4,"])
    assert dedupe_transcripts([old, b, c, new]) == [c, new, b]


def test_parser_skips_comments_and_blanks_and_strips_fields():
    lines = ["  # heading", "", " a , 2 , 0 ", " \t", "b, 3, "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad", ["a,2", "a,2,1,extra", "a,two,0"])
def test_parser_reports_original_line_number(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "a,1,1", " ", bad])


def test_daily_counts_and_window():
    events = parse_transcript_log(["a,1,1", "b,2,1", "c,2,1", "d,4,0", "e,5,1"])
    counts = daily_flag_counts(events, 2, 4)
    assert counts == [2, 0, 0]
    assert daily_flag_counts(events, 4, 2) == []
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 2) == 0
    assert flags_in_window(counts, 5) == 2


def test_summary_uses_pooled_rate_and_calendar_days():
    groups = {"a": parse_transcript_log(["a,1,1"]),
              "b": parse_transcript_log(["b,1,1", "c,4,0"]), "empty": []}
    assert pooled_flag_rate(groups) == 2 / 3
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rates_and_ranking():
    groups = {"z": [{"flagged": True}], "empty": [], "b": [{"flagged": False}],
              "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]
    assert list(flag_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", 0.0), ("empty", None), ("z", 1.0),
    ]


def test_streak_resets_on_nonpositive_days():
    assert longest_flag_streak([2, 0, 3, 1, -1, 4]) == 2
    assert longest_flag_streak([]) == 0
